document.addEventListener("DOMContentLoaded",function(e){const t=document.querySelectorAll(".eb-social-share-wrapper");t&&t.forEach(function(e){const t=e.querySelectorAll("ul.eb-social-shares li a");for(let e=0;e<t.length;e++)t[e].addEventListener("mouseenter",function(n){n.preventDefault(),t[e].classList.add("eb-slide-out")}),t[e].addEventListener("mouseleave",function(n){n.preventDefault(),t[e].classList.remove("eb-slide-out")})})});